<script>
(function($){function updateCounters(count){var u=$('[data-summary=unmapped]'),m=$('[data-summary=mapped]');u.text(Math.max(0,parseInt(u.text(),10)-count));m.text(parseInt(m.text(),10)+count);$('.mapping-tabs .nav-link:first .badge').text(Math.max(0,parseInt($('.mapping-tabs .nav-link:first .badge').text(),10)-count));}function submitNoReload(form,after){var button=$(form).find('[type=submit]');button.prop('disabled',true);$.ajax({url:$(form).data('url'),method:'POST',data:$(form).serialize(),dataType:'json'}).done(function(r){if(r.status){showSuccess(r.msg||'Saved.');after(r)}else showError(r.msg||'Could not save.')}).fail(function(){showError('The mapping action could not be completed safely.')}).always(function(){button.prop('disabled',false)})}$(document).on('submit.mappingWorkspace','#shopify-mapping-form',function(e){e.preventDefault();e.stopImmediatePropagation();var form=this;if(!$(form).find('[name=medicine_id]').val()){showError('Select an active ROOTINS medicine.');return}submitNoReload(form,function(){var variant=$(form).find('[name=shopify_variant_id]').val(),card=$('.mapping-select[value="'+variant+'"]').closest('.mapping-item');if(card.length){card.remove();updateCounters(1)}$('#shopifyMappingModal').modal('hide')})});$(document).on('submit.mappingWorkspace','#shopify-ignore-form',function(e){e.preventDefault();e.stopImmediatePropagation();var form=this;submitNoReload(form,function(){var variant=$(form).find('[name=shopify_variant_id]').val();$('.mapping-select[value="'+variant+'"]').closest('.mapping-item').remove();updateCounters(1);$('#shopifyIgnoreModal').modal('hide')})});$(document).on('submit.mappingWorkspace','#mapping-bulk-form',function(e){e.preventDefault();e.stopImmediatePropagation();var form=this,checked=$('.mapping-select:checked'),data=$(form).serializeArray(),variants=checked.map(function(){return {product_id:$(this).data('product-id'),variant_id:this.value,title:$(this).data('title')}}).get();if(!$(form).find('[name=medicine_id]').val()){showError('Choose an active ROOTINS medicine.');return}if(!window.confirm('Apply this medicine to '+variants.length+' Shopify variant(s)?'))return;data.push({name:'variants',value:JSON.stringify(variants)});$(form).find('[type=submit]').prop('disabled',true);$.post($(form).data('url'),data,function(r){if(r.status){showSuccess(r.msg||'Saved.');checked.closest('.mapping-item').remove();updateCounters(variants.length);$(form).addClass('d-none')}else showError(r.msg||'Could not save.')},'json').fail(function(){showError('Bulk mapping could not be completed safely.')}).always(function(){$(form).find('[type=submit]').prop('disabled',false)})})})(jQuery);
</script>
