<script>
(function($){function read(v){try{return JSON.parse(v||'{}')}catch(e){return {}}}function send(form,done){var button=$(form).find('[type=submit]');button.prop('disabled',true);$.ajax({url:$(form).data('url'),method:'POST',data:$(form).serialize(),dataType:'json'}).done(function(r){if(r.status){showSuccess(r.msg||'Saved.');done(r)}else showError(r.msg||'Could not save.')}).fail(function(){showError('The mapping action could not be completed safely.')}).always(function(){button.prop('disabled',false)})}function preview(item){$('#shopifyMappingModal [data-preview=title]').text(item.title_snapshot||'Untitled Shopify product');$('#shopifyMappingModal [data-preview=variant]').text('Variant '+(item.shopify_variant_id||'—'));$('#shopifyMappingModal [data-preview=ids]').text('Product '+(item.shopify_product_id||'—')+' · Variant '+(item.shopify_variant_id||'—'));$('#shopifyMappingModal [data-preview=sku]').text('SKU '+(item.sku||item.shopify_sku||'Not supplied'))}$(document).on('click','.js-map-medicine,.js-edit-mapping',function(){var item=read($(this).attr('data-item')||$(this).attr('data-mapping')),form=$('#shopify-mapping-form')[0];form.reset();preview(item);Object.keys(item).forEach(function(k){var field=form.querySelector('[name="'+k+'"]');if(field)field.value=item[k]||''});$('#shopify-mapping-form [name=medicine_id]').val(item.medicine_id||'');$('#shopifyMappingModal').modal('show')});$(document).on('input','#mapping-medicine-search',function(){var q=$(this).val().toLowerCase();$('[data-medicine-results] .medicine-option').each(function(){$(this).toggle($(this).text().toLowerCase().indexOf(q)!==-1)})});$(document).on('click','.medicine-option',function(){var m=read($(this).attr('data-medicine'));$('#shopify-mapping-form [name=medicine_id]').val(m.id);$('[data-suggestion-label]').text('Selected: '+m.medicine_name+' · '+(m.strength||'')+' '+(m.unit||''));$('[data-conflict-warning]').removeClass('d-none').text('Confirm this medicine matches the Shopify product.');});$(document).on('submit','#shopify-mapping-form',function(e){e.preventDefault();var form=this;if(!$(form).find('[name=medicine_id]').val()){showError('Select an active ROOTINS medicine.');return}send(form,function(){$('#shopifyMappingModal').modal('hide');setTimeout(function(){location.reload()},300)})});$(document).on('click','.js-ignore-mapping',function(){var item=read($(this).attr('data-item')),form=$('#shopify-ignore-form')[0];form.reset();form.querySelector('[name=shopify_product_id]').value=item.shopify_product_id||'';form.querySelector('[name=shopify_variant_id]').value=item.shopify_variant_id||'';$('#shopifyIgnoreModal [data-ignore-title]').text(item.title_snapshot||'Shopify product');$('#shopifyIgnoreModal').modal('show')});$(document).on('submit','#shopify-ignore-form',function(e){e.preventDefault();send(this,function(){$('#shopifyIgnoreModal').modal('hide');setTimeout(function(){location.reload()},300)})});$(document).on('change','.mapping-select',function(){var n=$('.mapping-select:checked').length;$('#mapping-bulk-form').toggleClass('d-none',n===0).find('[data-selected-count]').text(n)});$(document).on('submit','#mapping-bulk-form',function(e){e.preventDefault();var form=this,variants=$('.mapping-select:checked').map(function(){return {product_id:$(this).data('product-id'),variant_id:this.value,title:$(this).data('title')}}).get();if(!$(form).find('[name=medicine_id]').val()){showError('Choose an active ROOTINS medicine.');return}if(!window.confirm('Apply this medicine to '+variants.length+' Shopify variant(s)?'))return;var data=$(form).serializeArray();data.push({name:'variants',value:JSON.stringify(variants)});var button=$(form).find('[type=submit]');button.prop('disabled',true);$.post($(form).data('url'),data,function(r){if(r.status){showSuccess(r.msg||'Saved.');location.reload()}else showError(r.msg||'Could not save.')},'json').fail(function(){showError('Bulk mapping could not be completed safely.')}).always(function(){button.prop('disabled',false)})})})(jQuery);
</script><?= $this->endSection() ?>
